/*
 * A278545  Number of neighbors of the n-th term in a full square array read
 *          by antidiagonals.
 * https://oeis.org/A278545
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   a(n) = 3 for the top‑left cell, * 5 for cells on the first row
 *            or first column (excluding the corner), * otherwise 8. The
 *            sequence is generated by enumerating an infinite * 2‑dimensional
 *            grid of cells in antidiagonal order and counting the number * of
 *            8‑neighbour cells that each cell has
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* Handle offset: a(1) is defined.  For n < 1, return 0 (undefined). */
    if (n == (idx_t)0)
        return (seq_t)0;

    /* Find the diagonal k (0‑based) that contains the n‑th element.
       The total number of elements up to diagonal k is (k+1)(k+2)/2. */
    idx_t k = 0;
    while (1) {
        unsigned __int128 t = (unsigned __int128)(k + 1) * (k + 2) / 2;
        if (t >= n)
            break;
        ++k;
    }

    /* Compute how far into that diagonal the element lies. */
    unsigned __int128 prefix = (unsigned __int128)k * (k + 1) / 2;
    idx_t offset = (idx_t)(n - prefix - 1);          /* 0‑based offset */

    /* Coordinates in the grid: (i, j) where i = offset, j = k - offset. */
    idx_t i = offset;
    idx_t j = k - offset;

    /* Count neighbours: 3 for the single corner (0,0),
       5 for border cells (i==0 || j==0), otherwise 8. */
    if (i == 0 && j == 0)
        return (seq_t)3;
    if (i == 0 || j == 0)
        return (seq_t)5;
    return (seq_t)8;
}
